 "content": "from collections import Counter


def _bands(n, empty):
    bands = []
    i = 0
    while i < n:
        while i < n and empty(i):
            i += 1
        if i == n:
            break
        a = i
        while i < n and not empty(i):
            i += 1
        bands.append((a, i - 1))
    return bands


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rb = _bands(h, lambda r: all(v == 0 for v in grid[r]))
    cb = _bands(w, lambda c: all(grid[r][c] == 0 for r in range(h)))

    nonzero = Counter(v for row in grid for v in row if v != 0)
    if not nonzero:
        return out
    frame = nonzero.most_common(1)[0][0]

    colors = []
    for ri, (ra, rz) in enumerate(rb):
        row_colors = []
        for ci, (ca, cz) in enumerate(cb):
            counts = Counter(grid[r][c] for r in range(ra, rz + 1)
                             for c in range(ca, cz + 1)
                             if grid[r][c] not in (0, frame))
            row_colors.append(counts.most_common(1)[0][0] if counts else None)
        colors.append(row_colors)

    present = Counter(v for row in colors for v in row if v is not None)
    if not present:
        return out
    base = present.most_common(1)[0][0]

    # Each exceptional tile projects a short stroke into the adjacent gap
    # in any direction where another tile of that color occurs on the same
    # tile row or column. Intervening tiles remain untouched.
    for ri, row in enumerate(colors):
        ra, rz = rb[ri]
        for ci, color in enumerate(row):
            if color is None or color == base:
                continue
            ca, cz = cb[ci]
            feature_rows = [r for r in range(ra, rz + 1)
                            if any(grid[r][c] == color for c in range(ca, cz + 1))]
            if any(v == color for v in row[:ci]):
                ga, gz = cb[ci - 1][1] + 1, ca - 1
                for r in feature_rows:
                    for c in range(ga, gz + 1):
                        if out[r][c] == 0:
                            out[r][c] = color
            if any(v == color for v in row[ci + 1:]):
                ga, gz = cz + 1, cb[ci + 1][0] - 1
                for r in feature_rows:
                    for c in range(ga, gz + 1):
                        if out[r][c] == 0:
                            out[r][c] = color

    for ci in range(len(cb)):
        ca, cz = cb[ci]
        column = [colors[ri][ci] for ri in range(len(rb))]
        for ri, color in enumerate(column):
            if color is None or color == base:
                continue
            ra, rz = rb[ri]
            feature_cols = [c for c in range(ca, cz + 1)
                            if any(grid[r][c] == color for r in range(ra, rz + 1))]
            if any(v == color for v in column[:ri]):
                ga, gz = rb[ri - 1][1] + 1, ra - 1
                for r in range(ga, gz + 1):
                    for c in feature_cols:
                        if out[r][c] == 0:
                            out[r][c] = color
            if any(v == color for v in column[ri + 1:]):
                ga, gz = rz + 1, rb[ri + 1][0] - 1
                for r in range(ga, gz + 1):
                    for c in feature_cols:
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
