    # In each grid row, connect all appearances of a color. Existing cells
    # (including other tiles and their frames) are preserved; only blanks fill.
    for r in range(h):
        positions = {}
        for c, value in enumerate(grid[r]):
            if value not in (0, background):
                positions.setdefault(value, []).append(c)
        for color, cols in positions.items():
            if len(cols) >= 2:
                left, right = cols[0], cols[-1]
                for c in range(left + 1, right):
                    if out[r][c] == 0:
                        out[r][c] = color

    # The same rule vertically.
    for c in range(w):
        positions = {}
        for r in range(h):
            value = grid[r][c]
            if value not in (0, background):
                positions.setdefault(value, []).append(r)
        for color, rows in positions.items():
